from fractions import Fraction

def calculate_b_squared(x):
    # b^2 = x^2 + 4x + 3 - 2/x
    if x == 0:
        return None # Should not happen based on problem setup

    x_f = Fraction(x)
    # x^2 + 4x + 3
    term1 = x_f * x_f + 4 * x_f + 3
    # 2/x
    term2 = Fraction(2) / x_f

    b_squared = term1 - term2
    return b_squared

def is_rational_square(f):
    # Checks if a reduced fraction f = N/D is a perfect square of a rational number.
    if f.denominator == 0:
        return False

    N = f.numerator
    D = f.denominator

    # Handle zero case
    if N == 0:
        return True # 0 = 0^2

    # Check if N and D are perfect squares
    import math

    def is_perfect_square(n):
        if n < 0:
            return False
        s = int(math.isqrt(n))
        return s * s == n

    return is_perfect_square(N) and is_perfect_square(D)

# Test cases: x = +/- 1/k for k = 3, 4, 5
test_values = []
for k in [3, 4, 5]:
    test_values.append(1/k)
    test_values.append(-1/k)

results = {}
for x in test_values:
    b2 = calculate_b_squared(x)

    if b2 is None:
        continue

    is_square = is_rational_square(b2)

    results[x] = {
        "b^2": b2,
        "is_square": is_square
    }

print("--- Test Results ---")
for x, res in results.items():
    print(f"x = {x}: b^2 = {res['b^2']}. Is rational square? {res['is_square']}")
